@router.delete("/api/v1/service-accounts/{sa_id}/api-keys/{key_id}")
async def revoke_service_account_key(
    sa_id: str,
    key_id: str,
    db: AsyncSession = Depends(get_async_db),
    current_user: User = Depends(get_current_user)
):
    key_record = await db.execute(
        select(ServiceAccountKey).where(
            ServiceAccountKey.id == key_id,
            ServiceAccountKey.service_account_id == sa_id
        )
    )
    key = key_record.scalar_one_or_none()
    if not key:
        raise HTTPException(status_code=404, detail="Service account key not found")
    key.is_revoked = True
    await db.commit()
    return {"status": "revoked", "key_id": key_id}
